    "workbook": {
      "exercisesNote": "Luyện tập tr. 36–45\n1. Luyện âm và đọc cụm câu chữ 把 (tr. 36–37).\n2. Thay từ theo sáu nhóm mẫu (tr. 37–39).\n3. Chọn từ: 登机、放、装、倒、出来、系、屋子、插、把 (tr. 39).\n4. Điền động từ hoặc bổ ngữ (tr. 39–40).\n1) 你把这几件衣服给我洗____。\n2) 师傅，请把这辆车____。\n3) 希望大家把新课____。\n4) 你要想办法把他找____。\n5) 我已经把那本书____图书馆了。\n6) 我把手提包放____了。\n7) 你去银行把这些钱取____。\n8) 请把这张桌子搬到楼____。\n9) A：你把机票订____了吗？ B：还没有呢。\n10) A：你把作业____老师了没有？ B：我昨天就____了。\n5. Chọn vị trí cho từ trong ngoặc ở sáu câu (tr. 40).\n6. Dùng câu chữ 把 hoàn thành hội thoại (tr. 40–41).\n1) A：安全带怎么系？ B：____。\n2) A：照相机里的电池没电了。 B：____。\n3) A：把酒杯碰倒了，酒洒了一桌子。 B：没关系，____。\n4) A：空调开得太大了，我觉得有点儿冷。 B：____。\n5) A：外边刮大风了。 B：窗户还开着呢。____。\n7. Đổi câu khẳng định sang phủ định (tr. 41). Mẫu: 我把衣服洗完了。→ 我没把衣服洗完。／我还没把衣服洗完呢。\n1) 我把伞放在车里了。\n2) 她把电脑关上了。\n3) 我已经把书还给图书馆了。\n4) 我记得你已经把手机拿出来了。\n5) 我已经把那些照片寄回去了。\n6) 我把钥匙从车上拔下来了。\n7) 他把相机忘在家里了。\n8) 他们已经把鲁迅的这篇小说拍成电影了。\n8. Sửa tám câu sai (tr. 42).\n9. Dùng câu chữ 把 nói theo tình huống (tr. 42).\n1) 屋子里太热，你想请服务员把空调开开。\n2) 老师要你把作业本子给他，你还没有做完，怎么对老师说？\n3) 你去银行换钱，小姐问你换什么钱，你怎么说？\n4) 在火车上，一位老人想把他的提包放在行李架上，但他自己不能放上去，你要帮助他，怎么说？\n10. 综合填空 · 找钱 (tr. 43–44)\n下班以后，天都快黑①____，我想顺便买点菜带回家，就向一个菜摊走去。卖菜的是一个小伙子。问了价钱以后，我拿起一把菜，对他说：“②____这些菜给我称一下儿。”\n“您给三块吧！”他称了以后说。\n“给，找吧。”我给了他一张十元的钱。\n“您没零钱吗？”他问。\n“没有了，就这一张。”\n他找了半天，才把一把零钱放③____我手里说：“您数一数够吗？”\n我接过钱没有数，往口袋里一塞，拿起菜，骑上车就走了。\n骑了一会儿，我忽然觉得不对，就想，他找了我多少钱啊，我从车上下④____。从口袋里把钱拿出来认真地数⑤____数，小伙子找我了97元，多找给我90块钱。\n还回去不回去呢？已经走这么远了……\n就在我这么想的时候，脸上马上觉得发热。我怎么会有这种不好的想法，我的心也变坏了吗？\n想到这儿，就立刻骑上车回去找那个卖菜的小伙子。\n天已经黑了。我远远看见那个小伙子正准备走，就跑过去⑥____他叫住：“喂，等一下。”\n“怎么了？”小伙子问我。\n“你把钱找错了。”\n“少找了吗？”\n“不，你多找了。”\n“不会吧？”\n“怎么不会呢，你把我给你的十块钱看⑦____一百块的了。”我说，“给，这是你多找的九十块钱。”我把多找的钱还给他。\n他有点儿不太相信地把钱接过⑧____，很快，就感激地对我说：“谢谢了！大哥，谢谢你了！你真是好人。”\n我没有说话，骑上车就走了。这时，我心里才觉得轻松了。\n11. Tập viết (tr. 44–45).",
      "answerKeyNote": "Phụ lục tr. 158. Phụ lục ghi mục 7/9, tương ứng với mục 8/10 trong bài.\nMục 8. 1) 请把那本画报递给我看看。 / 我看看那本画报，好吗？\n2) 以前我见过天安门。\n3) 外边很冷，快把大衣穿上。\n4) 我来中国以后，很想朋友。\n5) 他能把五瓶啤酒喝完。 / 他能喝五瓶啤酒。\n6) 你知道，我很喜欢狗。\n7) 我看见玛丽进宿舍去了。\n8) 我来中国以前不会说汉语。\nMục 10. 1) 了 · 2) 把 · 3) 在 / 到 · 4) 来 · 5) 了 · 6) 把 · 7) 成 · 8) 去"
    },
