    "workbook": {
      "exercisesNote": "Luyện tập tr. 53–60\n1. Phân biệt âm, thanh điệu và đọc cụm từ (tr. 53).\n2. Thay từ trong bốn nhóm mẫu bị động (tr. 54–55).\n3. Chọn từ: 故意、偷、淋、要紧、骗、丢、罚、叫、撞、给 (tr. 55–56).\n4. Viết lại các câu với 被、叫、让 (tr. 56).\n1) 一个姑娘捡到我的钱包以后，给我送来了。\n2) 他不小心把杯子打碎了。\n3) 大风把树上的苹果刮掉了。\n4) 风把这棵小树都刮倒了。\n5) 玛丽把我的书借去了。\n6) 她把那些旧杂志都卖了。\n5. Dùng 被、叫、让 nói theo tình huống (tr. 56).\n1) 下课后，你发现同桌把你的书拿走了，把他的书给你留下了。\n2) 滑冰时把腿摔伤了，同学问你怎么了。\n3) 不小心把杯子碰到地上摔破了，妈妈问你，你怎么回答？\n4) 去看电影时才发现把票忘在家里了。朋友问你，你怎么说？\n5) 朋友从外边回来，衣服都被淋湿了，你请他把衣服换下来，怎么说？\n6. Sửa tám câu sai (tr. 57).\n7. 综合填空 · 我被解雇了 (tr. 57–58)\n“你还①____那家花店工作吗？”\n“不了，我②____老板炒鱿鱼了。”\n“为什么？”\n“每次给人家送花之前，我得在每束花里放上一③____卡片，上次，我把两张卡片放错了。”\n“你是怎么放④____？”\n“我⑤____送到婚礼上去的花里放上了一张‘致以深深的哀悼’；而那张新婚贺卡却被我放到了送给葬礼的花里去了。”\n“上面写的什么？”\n“祝你们⑥____新的家幸福快乐！”\n8. Đọc và nói 去医院看朋友 (tr. 58–59).\n9. Tập viết (tr. 59–60).",
      "answerKeyNote": "Phụ lục tr. 158.\nMục 6. 1) 我的衣服都被雨淋湿了。\n2) 真对不起，你的照相机让我弄坏了。 / 真对不起，你的照相机让我摔坏了。\n3) 我买了他的自行车。 / 他把自行车卖给我了。\n4) 我也差点儿被自行车撞倒。\n5) 我忘把钥匙拔下来了。 / 钥匙我忘拔下来了。\n6) 我们班有好几个同学都感冒了。\n7) 我们刚到公园就下雨了。\n8) 今天的作业我还没做完呢。 / 今天的作业我没做完。\nMục 7. 1) 在 · 2) 被 · 3) 张 · 4) 的 · 5) 把 · 6) 在"
    },
