    "workbook": {
      "exercisesNote": "Mục 1. Ngữ âm, tr. 70–71.\nMục 2. Thay thế theo mẫu, tr. 71–72.\nMục 3. Chọn từ, tr. 73–74. Nhóm từ 3A gồm 肯定、影响、估计、性格、内容、只是、担心、艺术、武打、只好。\nMục 4. Điền cụm từ, tr. 74. Nhóm từ gồm 看不懂、看得完、拿不了、放不下、参加得了、买得到、坐不下、听不懂、出不去、起得来。\nMục 5. Hoàn thành hội thoại, tr. 74–75.\nMục 6. Sửa câu, tr. 75–76.\nMục 7. Dùng bổ ngữ khả năng nói theo tình huống, tr. 76.\nMục 8. Điền vào bài đọc, tr. 76–77.\n南辕北辙\n这是中国古代的一个故事。\n前边跑过来了一辆马车，①____坐着一个大富翁，后面放着一个大箱子，前面还坐着一个赶车的。赶车的不停地赶着马，马车跑②____飞快。\n路上走过来一位老人。老人挑着水。\n大富翁看见这位老人，③____叫赶车的停下车，想向老人要点儿水喝。\n老人问他们要到什么地方去，富翁大声地说：“我们要到楚（Chǔ）国去。”\n老人一听就笑了，他对富翁说：“你们走错了，楚国在南边，应该往南走，怎么往北走呢？”\n富翁说：“没关系，你看，我的马跑得很④____。”\n老人又说：“你的马跑得再快，⑤____这不是去楚国的路啊。马跑得越快离楚国越远。”\n“没问题。”大富翁指着车上的箱子说：“您看，这个大箱子里装着很多钱呢。”\n“你有很多钱，可是走的方向不对，是到不了楚国的。”\n大富翁又指着赶车的说：“你看我这个车夫，身强力壮，赶车的技术也特别好。”\n老人觉得这位先生简直不懂道理，⑥____，说：“你的车夫是不错。可是，楚国在南边，你非要他赶着车往北跑，⑦____能到得了楚国呢？”\n大富翁听了老人的话，不高兴地说：“我们已经走⑧____好几百里路了，怎么能再往回走呢？”\n说完他就让赶车的继续赶着车一直往北跑去，车越跑越快，一会儿就看不见了。\nMục 9. Tập viết, tr. 78.",
      "answerKeyNote": "Đáp án mục 6, tr. 159.\n1. 中文广播说得太快了，我听不懂。\n2. 今天的作业太多了，我做到十点也没做完。\n3. 你中文小说看得懂看不懂？ / 你看得懂中文小说吗？\n4. 因为买不着机票，今天我回不去。 / 因为买不到机票，今天我回不去。\n5. 今天的作业我做得完。\n6. 刚来中国时，我一句汉语也听不懂。\n7. 这些菜你吃得完吃不完？\n8. 这个包放不下这么多书。\nĐáp án mục 8, tr. 159.\n1. 车上\n2. 得\n3. 就\n4. 起16\n5. 但是\n6. 就\n7. 怎么\n8. 了\nỞ ô ④, bản in phần đáp án hiện “起16”, còn đoạn sau dùng 快 để nói về tốc độ. Ở ô ⑥, bản in đặt dấu phẩy trước 说 dù đáp án là 就. Hai ô này dành để đối chiếu."
    },
