    "workbook": {
      "exercisesNote": "Mục 1. Ngữ âm, tr. 86.\nMục 2. Thay thế theo mẫu, tr. 86–88.\nMục 3. Chọn từ, tr. 88–89. Nhóm từ gồm 加油、动、联欢会、积极、相信、放、下、怕、演、纠正、背。\n(3) A：在比赛时不停地喊“____！____！”的那些人叫什么？ B：叫拉拉队（lālāduì）。\n(5) 星期六晚上，我们班开了一个____，我在会上____了一个节目。\n(10) 不少同学的问题是____说错，学习外语一定不要____说错，越____说错越不敢说，也就越不会说。\nMục 4. Chọn cụm từ, tr. 89. Nhóm từ gồm 学得了、学不了、记得住、记不住、修不好、修不了、上得去、上不去、用得了、用不了、找得到、找不到、走得动、走不动、搬得动、搬不动、参加得了、参加不了、放不进去、放得进去、爬得上去、爬不上去。\n(3) 我们一年____五千个词。\n(6) 你这台电视机太旧了，可能____了，换一台新的吧。\nMục 5. Hoàn thành hội thoại, tr. 89–90.\n(1) A：明天的晚会你能参加吗？ B：我能参加。 A：罗兰呢？ B：她可能____。 A：为什么？ B：她去大同了，明天____。\n(2) A：请你填一下这张表。 B：对不起，有没有法文的，汉语的我____。 A：英文的你填得了吗？ B：英文的我也____。 A：那怎么办呢？\nMục 6. Sửa câu, tr. 90.\nMục 7. Nói theo tình huống, tr. 91.\n(1) 一个女同学拿了很多东西，你想帮助她拿，怎么说？\n(2) 想把一个冰箱搬出去，你一个人搬不动，想请朋友帮忙，怎么说？\n(3) 老师说明天要听写25个生词，你觉得太多，记不住，怎么说？\n(4) 去邮局给国内的朋友寄书，你想知道什么时候能收到，怎么问？\n(5) 你穿二十六号的鞋（xié），售货员给你了一双二十五号的鞋，你怎么说？\nMục 8. Đọc và nói, tr. 91–92.\n画蛇添足\n从前，有几个人得到了一壶酒。他们谁都想喝这壶酒，可是这壶酒只够一个人喝，给谁喝呢，半天决定不了。一个人说：“这样吧，我们每个人都在地上画一条蛇。谁先画完，这壶酒就给谁喝。”\n大家都同意他的办法，于是就在地上画了起来。\n有一个人很快把蛇画好了。他看别人还都没有画完，就左手拿起酒壶，右手又画起来，还得意地说：“你们画得太慢了！你们看我，还能给蛇添上几只脚呢。”\n当他正在给蛇画脚的时候，另一个人也把蛇画好了，就把酒壶拿了过去，说：“蛇是没有脚的，你给它画上了脚，就不是蛇了。所以，第一个画完蛇的是我，不是你！”说完就把酒喝了。\nMục 9. Tập viết, tr. 92–93.",
      "answerKeyNote": "Đáp án mục 6, tr. 159.\n1. 门太小了，这个沙发搬不进去。\n2. 今天我们见得了面吗？ / 今天我们能见面吗？\n3. 这个书柜我们两个搬不动。\n4. 你要的菜太多了，我们肯定吃不了。 / 你要的菜太多了，我们肯定吃不完。\n5. 天太黑了，我什么都看不见。\n6. 这个包放不下这么多书。\nỞ câu (3), đề in dùng 书架 và 抱, còn phụ lục in 书柜 và 搬. Câu tương tác giữ cách sửa của phụ lục."
    },
