    "workbook": {
      "answerKeyNote": "Sửa câu sai\n1. 他照出来的照片很好看。 / 他洗出来的照片很好看。\n2. 这个词我查不出来。 / 这个词我没查出来。\n3. 因为家里没有钱，没办法让我继续学下去了。\n4. 我想不起来她叫什么名字了。\n5. 他想出来了一个办法。\n6. 这件事我不想告诉她，但是她已经知道了。\n\nĐiền tổng hợp\n1. 进\n2. 起来\n3. 去\n4. 起\n5. 出来\n6. 把\n7. 出\n8. 起来",
      "exercisesNote": "Luyện tập tr. 101–108. Mục 1 ngữ âm và mục 2 thay thế ở tr. 101–104. Mục 3A chọn từ tr. 104–105, mục 3B chọn bổ ngữ tr. 105–106. Mục 6 sửa câu sai tr. 107–108, mục 7 điền tổng hợp “司马光砸缸” tr. 108, đáp án tr. 159–160. Tập viết tr. 108–109.\nMục 3B. Chọn từ điền trống (tr. 105–106).\n1. 他说明年还要在这个学校____。（学下去／学下来／学起来／学上来）\n2. 他的电话号码是多少，我____了。（想不起来／想不出来／想起来／想出来）\n3. 你____了没有，这是谁唱的歌？（听起来／听出来／听不出来／听起来）\n4. 我____了，我看过她演的电影。（想起来／想出来／想不起来／想不出来）\n5. 她难过得____了。（说不上来／说不下去／说不下来／说不出来）\n6. 你____了吗？这是什么茶？（喝得出来／喝不下去／喝不出来／喝出来）\n7. 这儿风景真美，快把它____吧。（拍进来／拍下来／拍下去／拍出来）\n8. 一看到他那样子，大家就都____。（笑了起来／笑了一下／笑了出来／笑了一会儿）\n9. 你能____她是哪国人吗？（看得出来／看得过来／看得起来／猜得到）\n10. 我也____好办法。（想出来／想不起来／想不出来／想不到）\nMục 4. Luyện theo mẫu và nói khi nào dùng các câu sau (tr. 106).\nMẫu 1. 把它拍下来吗？／拍下来吧。你把它拍下来了没有？／拍下来了。 Thay động từ bằng 照、画、录、写、记。\nMẫu 2. 听出来了吗？／听不出来。 Thay động từ bằng 看、猜、吃、喝、想。\nMục 5. Dùng động từ và bổ ngữ xu hướng để nói theo tình huống (tr. 106–107).\n1. 在一次会上，一个多年不见的同学走过来，跟你握手，但是你认不出来他是谁了。同学：还认识我吗？ A：对不起，____。\n2. 朋友请你吃饭，一个菜很好吃，朋友问你，是什么菜，你吃得出来吗。你吃不出来，怎么回答？\n3. 老师让你们听写，但是你觉得老师念得太快，有两个句子没有写下来…… 老师：都写下来了吗？ A：____。\n4. 去洗照片，你希望一个小时以后能洗出来，怎么问？ A：____？ B：没问题，洗得出来。\n5. 听到一个小提琴曲，朋友问你听得出来这是什么曲子吗？你怎么回答？\nMục 7. Điền tổng hợp (tr. 108).\n司马光砸缸\n这是中国古时候的故事。\n有一天，司马光和小朋友们在院子里玩，院子里有个大水缸，水缸里装满了水，他们玩得正高兴的时候，一个小朋友不小心掉①____水缸里去了，一个孩子看见了，就大声喊了②____：“救人啊！救人啊！有人掉到水缸里③____了。”有的孩子吓得哭了④____来。司马光看到这种情况，很快想⑤____了一个好办法。他连忙搬起一块石头，跑了过来，向着水缸砸去，一下子⑥____水缸砸破了。水缸里的水都流了⑦____来。掉在水缸里的小朋友得救了。\n看到从水缸里爬出来的小朋友，大家都笑了⑧____……"
    },
