    "workbook": {
      "answerKeyNote": "Sửa câu sai\n1. 哪个题容易，我就做哪个。\n2. 你怎么说，我就怎么做。\n3. 哪儿好玩儿，我们就去哪儿玩儿。\n4. 我的电脑坏了，怎么也修不好。\n5. 我刚来中国的时候，什么话也不会说。 / 我刚来中国的时候，一句汉语不会说。\n6. 老师的话我听不懂。 / 老师的话我一边听，一边想。",
      "exercisesNote": "Luyện tập tr. 117–122. Mục 1 ngữ âm tr. 117. Mục 2 thay thế tr. 117–119. Mục 3 chọn từ tr. 119. Mục 7 sửa câu sai tr. 121–122, đáp án tr. 160. Bài đọc và nói “吃药吃的” tr. 122. Tập viết tr. 123.\nMục 4. Dùng từ trong ngoặc để hoàn thành câu (tr. 119–120).\n1. 她怎么样？／她又聪明又漂亮，班上的同学____。（谁）\n2. 你今天出去吗？／今天外边太冷，我____。（哪儿）\n3. 你看这件事怎么办呢？／____。（怎么）\n4. 我想去看看你，什么时候去比较合适？／你____。（什么）\n5. 来中国以后，你去过什么地方？／除了北京以外，我____。（哪儿）\n6. 我们坐火车去还是坐飞机去？／____。（怎么）\nMục 5. Trả lời bằng cấu trúc trong ngoặc (tr. 120).\n1. 你想吃点儿什么？（什么……什么……）\n2. 你想让谁跟你去？（谁……谁……）\n3. 我们怎么去呢？（怎么……怎么……）\n4. 我们什么时候出发？（什么……什么……）\n5. 我们去哪儿买？（哪儿……哪儿……）\n6. 你想学哪本书？（哪……哪……）\nMục 6. Nói lại theo tình huống, dùng từ nghi vấn đã cho (tr. 121).\n1. 你们班的同学有的以后要学经济，有的要学法律，有的要学医学，有的要学历史……（什么）\n2. 我有很多朋友，有的是老师，有的是记者，有的是作家，有的是工程师，有的是大夫，有的是律师……（什么）\n3. 我喜欢看书，文学、历史、医学、经济、法律等方面的书我都喜欢看。（什么）\n4. 他来中国快一年了，只去过一次北京，别的地方还没有去过。（除了……以外，哪儿）\nMục 8. Đọc và nói (tr. 122).\n吃药吃的\n因为吃得好也吃得多，我越来越胖。天冷了，为了减肥，我决定去游泳。那天，我去奥林匹克体育中心游泳馆游了一会儿泳，第二天头就疼起来了。我到医院去看病。大夫说我感冒了，开了一些药让我吃。吃了感冒药就想睡觉。睡了两天以后，头不疼了，但是嗓子却疼起来了。大夫说，天气太干燥，又让我吃药。过了三天，嗓子不疼了，又咳嗽起来了，而且越咳越厉害，咳得晚上睡不着觉。大夫看了以后给我开了一些咳嗽药。没想到，当天晚上我就发起烧来了。大夫只好又给我开退烧药。他说这药很好，但是要多喝水。\n药真的很好，很快就不发烧了。但是好几天没有大便了。大夫一检查说我大便干燥。这次，大夫说吃点儿中药吧。中药也很好，吃了以后，第二天就有了要大便的感觉，连忙去厕所，没想到又拉起肚子来了。去找大夫，他说我把肚子吃坏了，再开点儿治肚子的药吃吃吧。\n昨天下午，一位当医生的朋友来看我。他说：“你的脸色怎么这么难看，我给你开点儿药吃吃吧。”我说，不用了。我这难看的脸色都是吃药吃的。\n他好像听不懂我的话，我就把这些天看病的经过跟他说了说，他听了以后大笑起来，对我说，是，是，你不能再吃药了。不过，应该去运动运动。冬天太冷，到外边运动容易感冒，到奥体中心去游游泳吧。我一听他的话，头又立刻疼了起来。"
    },
