    "workbook": {
      "exercisesNote": "Mục 1. Luyện âm, tr. 147.\nMục 2. Thay thế theo mẫu, tr. 147–149.\nMục 3. Chọn từ, tr. 149–150. Ngân hàng từ gồm 感情、笨、认为、领导、首先、连、申请、玩笑、长久、简单。\nMục 4. Nối vế câu, tr. 150.\nMục 5. Hoàn thành đối thoại bằng câu phản vấn, tr. 150–151.\n(1) A：来中国以前，她没学过汉语。 B：____？（谁说……）\n(2) A：你没看过这个电影，你怎么知道没有意思。 B：____？（谁说……）\n(3) A：你知道这件事吗？ B：____？（怎么……）\n(4) A：我的钥匙怎么找不到了？ B：____？（不是……吗）\n(5) A：听说小张去美国留过学。 B：____？（哪里……）\n(6) A：你知道玛丽去哪儿了？ B：____？我今天一天都没看见她。（谁……）\nMục 6. Trả lời bằng 连……也／都……, tr. 151.\n(1) 听力考试难吗？ → 很难，____。\n(2) 来中国以前你学过多长时间汉语？ → ____。\n(3) 听说她结婚了。 → 胡说，____，跟谁结婚呢？\n(4) 来中国以后你去旅行过几次？ → ____。\n(5) 你读过鲁迅的作品吗？ → ____。\n(6) 今天你来得早吗？ → 来得很早，我来时____。\n(7) 她回国以后常给你写信吗？ → ____。\n(8) 这些书你看完几本了？ → 我刚借来，____。\nMục 7. Dùng câu phản vấn theo tình huống, tr. 152.\n(1) 朋友在找钥匙，你看她的钥匙就在桌子上，你怎么说？\n(2) 朋友问你的老师叫什么名字，你说不知道，你的朋友会怎么说？\n(3) 朋友问你桂林的风景怎么样，但是你没去过，怎么说？\n(4) 有人说你当过演员，但是你没有当过演员，怎么说？\n(5) 有人找玛丽，但玛丽不在，她问你，但你不知道，怎么说？\nMục 8. Sửa câu, tr. 152.\n(6) 我以前连一次也没有来过中国。 Đối chiếu hai cách viết trong phụ lục tr. 161.\nMục 9. Điền vào bài đọc, tr. 153–155.\n哪个数字最吉利\n看到很多朋友买了汽车，李四也买了一辆。去办理牌照的时候，营业员①____他说，如果多交50元，车牌的最后一个号码可以随便挑。李四就多交了50块钱。\n营业员说，从0到3，从5到9，您选哪个数字呀？\n李四说，我自己决定不②____，让我回去跟妻子商量商量，一会儿我再来告诉您。\n营业员笑着说，您快点儿啊。\n李四说，一会儿就来。\n李四回到家，对妻子讲了挑号码的事。妻子说，就挑8嘛，还跟我商量什么，这几年只要带8字的东西都卖得快，这个数字最吉利。\n李四说，8跟伤疤的“疤”同音，不太好，我看6比较合适，六六大顺，你看行不行。\n妻子说，6和“流”谐音，流氓，流浪，多难听。我看9这个数不错，你说呢？\n李四说，9好什么？九泉，人一死就说去了九泉。9又和“救”谐音，救济、救命，都是不吉利的词。还是5吧，你看5怎么样？\n妻子说，5更不好了！要是倒数第二位是2、7、8的话，你念念，不就成了儿无、妻无、爸无了吗？另外，5与污染的“污”谐音，不干净。不能要5，还是7这个数合适。\n李四说，7和“凄惨”的“凄”同音，也不好。\n妻子说，选3行不行？\n李四摇摇③____说，三就是散，就是离婚，多不吉利呀，你想想2可以不可以？\n妻子分析说，二流子、二百五，都和二有关。二和儿谐音，当儿子有低人一等的感觉。不行，不行。\n李四说，那就选1吧。\n妻子说，你怎么糊涂了，1是什么好数字呀！一团糟、一场空，1的贬义词太多。\n李四说，没关系，在电话号码中人们不说一，说幺（yāo）。\n妻子说，那就更不好了，“幺”和“夭”同音，夭折不就是死了吗？这个更不行了。\n李四说，那就用0吧，0怎么看都是0，永远不会看错。\n妻子说，0和“灵”同音，灵堂、灵车，都和死人④____关系，最不吉利了。\n李四说，那就只有4了，我认为这个数字不坏，四季发财，我李四从小到大，平安无事地长这么大，就是和“4”有关系。\n妻子说，别说了，四就是死，谁不知道这是个倒霉的数字，我们要选这个数，人家会笑掉牙的。\n李四说，0到9我们都研究过了，都不行，你说怎么办？\n妻子说，从0到9，每张纸上各写一个数字，揉成纸团，抓到哪个是⑤____吧。\n李四说，这个办法不错。妻子写好后，⑥____纸团放在一起，李四随便抓了一个，打开一看……\n妻子生气地哭⑦____。\n李四又来到办牌照的地方，把纸递给营业员说，就要这个数。\n营业员办完手续后又把50块钱还⑧____了李四。\n李四问，这50块钱怎么又还给我了？\n营业员说，你选的这个数不加钱。\nMục 10. Tập viết, tr. 156.",
      "answerKeyNote": "Đáp án mục 8, tr. 161.\n1. 你不是要把生词预习预习吗？\n2. 只要你努力，就能学好汉语。\n3. 只要汉语说得好，我就能找到工作。\n4. 连我都看得懂说明书，你更能看得懂了。\n5. 连她都不会做这个题，我更不会了。\n6. 我以前连一次中国也没有来过。 / 中国我以前连一次也没有来过。\nĐáp án mục 9, tr. 161.\n1. 对　2. 了　3. 头　4. 有　5. 哪个　6. 把　7. 了　8. 给"
    },
